// The Mirror Realm's generator (Phase 9): the Surface, reflected. Each column is the Surface
// column on the other side of the mirror x -> -x - 1 (generated by a Surface generator with the
// same seed and no structures), flipped along x and repainted in the Mirror palette: the ground of
// each Surface biome becomes the ground of the Mirror biome that reflects it (mirrorBiomeFor), and
// plants on solid ground become that biome's own plants. Heights, rivers, lakes, caves and ores
// are the Surface's own, so the landmarks correspond: climb a hill here and its twin stands over
// there, mirrored. Structures of the Mirror Realm itself are placed afterwards (StructureGen).
//
// Deterministic and worker-safe; `sample()` reflects the Surface sample, so structures, spawning
// and atlases agree with the blocks.

import { REG, hexToRgb } from '../../content/registry';
import { MIRROR_PALETTES, flipCell, mirrorBiomeFor } from '../../content/mirror';
import { REALMS } from '../../content/realms';
import type { RealmDef } from '../../content/types';
import { hash4 } from '../../math/rng';
import { SurfaceGenerator, type ColumnSample, type GenOptions } from './SurfaceGen';
import { StructureGen, type GenExtra } from './structures/StructureGen';

const COL = 4096;

export class MirrorGenerator {
  readonly seed: number;
  readonly realm: RealmDef;
  readonly height: number;
  readonly sea: number;
  garden = false;
  gardenOrigin: [number, number, number, number] = [0, 0, 0, 0];
  /** The Surface this realm reflects. */
  readonly base: SurfaceGenerator;

  private readonly tmpBlocks: Uint16Array;
  private readonly tmpSurface = new Uint8Array(4096 * 4);

  // Per Surface biome index: the ids that make its ground, and the Mirror biome that reflects it.
  private readonly fromSurface = new Int32Array(256).fill(-1);
  private readonly fromSub = new Int32Array(256).fill(-1);
  private readonly fromUnder = new Int32Array(256).fill(-1);
  private readonly fromStone = new Int32Array(256).fill(-1);
  private readonly toBiome = new Int32Array(256).fill(-1);
  // Per Mirror biome index: its ground blocks, plants and tint.
  private readonly toSurface = new Int32Array(256).fill(-1);
  private readonly toSub = new Int32Array(256).fill(-1);
  private readonly toUnder = new Int32Array(256).fill(-1);
  private readonly toStone = new Int32Array(256).fill(-1);
  private readonly plantA = new Int32Array(256).fill(-1);
  private readonly plantB = new Int32Array(256).fill(-1);
  private readonly tint = new Uint8Array(256 * 3);
  private readonly isPlant = new Uint8Array(4096);
  private readonly stoneId: number;
  private readonly deepStone: number;

  constructor(seed: number, realm: RealmDef, options: GenOptions = {}) {
    this.seed = seed;
    this.realm = realm;
    this.height = realm.heightChunks * 16;
    this.sea = realm.seaLevel;
    const surfaceRealm = REALMS.find((r) => r.name === 'surface')!;
    this.base = new SurfaceGenerator(seed, surfaceRealm, { ...options, garden: false, structures: false });
    this.tmpBlocks = new Uint16Array(COL * this.height);
    this.stoneId = REG.id('stone');
    this.deepStone = REG.id('silvered_stone');

    const byName = new Map(REG.biomes.map((b, i) => [b.name, i]));
    REG.biomes.forEach((b, i) => {
      if (b.realm && b.realm !== 'surface') return;
      if (b.kind === 'underground') return;
      const mb = byName.get(mirrorBiomeFor(b))!;
      this.toBiome[i] = mb;
      if (b.surface) this.fromSurface[i] = REG.id(b.surface);
      if (b.subsurface) this.fromSub[i] = REG.id(b.subsurface);
      if (b.underwater) this.fromUnder[i] = REG.id(b.underwater);
      if (b.stone) this.fromStone[i] = REG.id(b.stone);
    });
    for (const [name, pal] of Object.entries(MIRROR_PALETTES)) {
      const mb = byName.get(name)!;
      const def = REG.biomes[mb]!;
      this.toSurface[mb] = REG.id(pal.surface);
      this.toSub[mb] = REG.id(pal.subsurface);
      this.toUnder[mb] = REG.id(pal.underwater);
      this.toStone[mb] = REG.id(pal.stone);
      this.plantA[mb] = REG.id(def.plants[0]!.block);
      this.plantB[mb] = REG.id(def.plants[1]!.block);
      const [r, g, b] = hexToRgb(def.grassColor);
      this.tint[mb * 3] = Math.round(r * 255);
      this.tint[mb * 3 + 1] = Math.round(g * 255);
      this.tint[mb * 3 + 2] = Math.round(b * 255);
    }
    REG.blocks.forEach((b, id) => {
      if (b.tags?.includes('plant') && !b.solid) this.isPlant[id] = 1;
    });
  }

  spawnPoint(): [number, number, number, number] {
    const [x, y, z, w] = this.base.spawnPoint();
    return [-x, y, z, w];
  }

  /** The Surface sample on the other side of the mirror, with the reflecting Mirror biome. */
  sample(x: number, z: number, w: number, out: ColumnSample): ColumnSample {
    this.base.sample(flipCell(Math.floor(x)), z, w, out);
    const mb = this.toBiome[out.biome]!;
    if (mb >= 0) {
      out.biome = mb;
      out.grass = [this.tint[mb * 3]! / 255, this.tint[mb * 3 + 1]! / 255, this.tint[mb * 3 + 2]! / 255];
    }
    return out;
  }

  caveBiomeAt(x: number, y: number, z: number, w: number): number {
    return this.base.caveBiomeAt(flipCell(Math.floor(x)), y, z, w);
  }

  growTreeAt(blocks: Uint16Array, x: number, y: number, z: number, w: number, name: string, X: number, Z: number, W: number): void {
    this.base.growTreeAt(blocks, x, y, z, w, name, X, Z, W);
  }

  private structGen: StructureGen | null = null;
  get structures(): StructureGen {
    return (this.structGen ??= new StructureGen(this));
  }

  nearestStructure(names: string[], x: number, z: number, w: number, maxDist = 1200): { name: string; x: number; y: number; z: number; w: number } | null {
    const st = this.structures.placer.nearest(names, x, z, w, maxDist);
    return st ? { name: st.def.name, x: st.x, y: st.y, z: st.z, w: st.w } : null;
  }

  generate(cx: number, cz: number, cw: number, blocks: Uint16Array, surface: Uint8Array, extra?: GenExtra): void {
    const H = this.height;
    const src = this.tmpBlocks;
    const ssrc = this.tmpSurface;
    this.base.generate(-cx - 1, cz, cw, src, ssrc);
    blocks.fill(0);
    const stoneId = this.stoneId;
    const X0 = cx * 16, Z0 = cz * 16, W0 = cw * 16;
    for (let w = 0; w < 16; w++)
      for (let z = 0; z < 16; z++) {
        const row = 16 * z + 256 * w;
        for (let xm = 0; xm < 16; xm++) {
          const col = row + xm, colS = row + (15 - xm);
          const sb = ssrc[colS * 4 + 3]!;
          const mb = this.toBiome[sb]!;
          surface[col * 4 + 3] = mb >= 0 ? mb : sb;
          if (mb < 0) {
            // Not a land or sea biome (cannot happen for surface columns): copy as it is.
            for (let y = 0; y < H; y++) blocks[col + y * COL] = src[colS + y * COL]!;
            continue;
          }
          surface[col * 4] = this.tint[mb * 3]!;
          surface[col * 4 + 1] = this.tint[mb * 3 + 1]!;
          surface[col * 4 + 2] = this.tint[mb * 3 + 2]!;
          const fSurf = this.fromSurface[sb]!, fSub = this.fromSub[sb]!, fUnder = this.fromUnder[sb]!, fStone = this.fromStone[sb]!;
          const tSurf = this.toSurface[mb]!, tSub = this.toSub[mb]!, tUnder = this.toUnder[mb]!, tStone = this.toStone[mb]!;
          let ground = -1;
          for (let y = H - 1; y >= 0; y--) {
            const v = src[colS + y * COL]!;
            const id = v & 0xfff;
            if (id === 0) continue;
            let nid = id;
            if (id === fSurf) nid = tSurf;
            else if (id === fSub) nid = tSub;
            else if (id === fUnder) nid = tUnder;
            else if (id === stoneId || id === fStone) nid = ground >= 0 && ground - y > 14 ? this.deepStone : tStone;
            else if (this.isPlant[id] && y > 0 && REG.solid[src[colS + (y - 1) * COL]! & 0xfff] && !this.isPlant[src[colS + (y - 1) * COL]! & 0xfff]) {
              nid = (hash4(X0 + xm, y, Z0 + z, W0 + w, this.seed) & 1) === 0 ? this.plantA[mb]! : this.plantB[mb]!;
            }
            if (ground < 0 && (id === fSurf || id === fSub || id === fUnder || id === stoneId || id === fStone)) ground = y;
            blocks[col + y * COL] = nid === id ? v : (v & 0xf000) | nid;
          }
        }
      }
    this.structures.apply(cx, cz, cw, blocks, extra ?? {});
  }
}
